mapper.select:
select id, car_no, car_color, vehicle_type, driving_license_url, driver_card, employee_name, employee_no, phone_no, dept_no, myself_car, publish_time, lock_flag, img_url1, img_url2, img_url3, relationship, server_end_date, car_type, car_model, auth_factory, section_chief_name, section_chief_no, car_affiliation_personnel, driver_personnel_name, driver_license_start_date, driver_license_end_date, other_remark from safety_employee_private_car where delete_flag = '0'
AND car_no LIKE CONCAT('%', #{query.carNo}, '%')
AND car_color = #{query.carColor}
AND vehicle_type = #{query.vehicleType}
and employee_name = #{query.employeeName}
and employee_no = #{query.employeeNo}
and phone_no = #{query.phoneNo}
and dept_no = #{query.deptNo}
and myself_car = #{query.myselfCar}
order by publish_time desc
